 @AfterEach void cleanup(){if(admin!=null&&schema!=null)admin.execute("drop schema "+schema+" cascade");}
 private long count(String kind){return jdbc.queryForObject("select count(*) from plm_partner_record where kind=?",Long.class,kind);}
 private Map<String,Object> receipt(){return values("sourceType","catalog","selectionId",900L,"selectionRowId",snapshot.get("selectionRowId"),"phoneModelId",18L,"colorId",5L,"qty",2L,"date","2026-10-22","location","QA公司样品柜","person","QA国内工程","requestId","QA-receive");}
 private Map<String,Object> receive(){return tx.execute(s->samples.create(receipt()));}
 private static final String ROW_A="00000000-0000-0000-0000-000000000090",ROW_B="00000000-0000-0000-0000-000000000091";
 private void batchSource(boolean lateColor){
  jdbc.execute("delete from plm_partner_selection_row; create table plm_supplier_color(color_id bigint primary key,supplier_code text,name text,code text,supplier_color_code text default '',style_key text default '',config_key text default '',status text default 'active',version bigint default 1); insert into plm_supplier_color(color_id,supplier_code,name,code) values(5,'QA-XD','黑色','QA-BLACK'),(7,'QA-XD','蓝色','QA-BLUE'),(9,'OTHER','其他供方红色','QA-OTHER')");
  jdbc.update("insert into plm_partner_record(record_id,kind,code,name,version,data) values(900,'selection','SL-000900','QA已选样',3,?::jsonb) on conflict(record_id) do update set data=excluded.data,version=excluded.version",encode(store.json,values("name","QA已选样","purpose","my_selection","version",3L)));
  jdbc.update("insert into plm_partner_file values(900,1,'material')");
  var actual=spy(new PartnerCatalogStyles(store));for(String rid:List.of(ROW_A,ROW_B)){
   var frozen=copy(store.json,snapshot);frozen.put("phoneModelIds",List.of(18L));frozen.put("specification","QA支架");frozen.put("selectedPairs",lateColor?List.of():List.of(values("phoneModelId",18L,"colorId",5L,"colorSnapshot",values("id",5L,"name","黑色"))));
   var data=values("supplierCode","QA-XD","name",rid.equals(ROW_A)?"QA款A":"QA款B","confirmed",true,"selectionConfirmationVersion",2L,"receiptColorMode",lateColor?"at_receipt":"selected_pairs","confirmationSnapshot",values("row",frozen));
   jdbc.update("insert into plm_partner_selection_row(row_id,record_id,data) values(?::uuid,900,?::jsonb)",rid,encode(store.json,data));
   doReturn(values("catalogStyleId",rid.equals(ROW_A)?23L:24L,"catalogStyleCode",rid.equals(ROW_A)?"CP-000023":"CP-000024","catalogStyleLabel",rid.equals(ROW_A)?"XD-CP-000023":"XD-CP-000024")).when(actual).identity("selection",900L,rid);
  }ReflectionTestUtils.setField(samples,"catalogStyles",actual);
 }
 private Map<String,Object> batchRequest(){return values("version",3L,"requestId","QA-bulk-receipt","date","2026-10-22","location","QA公司柜","ownerName","QA国内工程","rows",List.of(values("clientRowId","first","rowId",ROW_A,"rowVersion",4L,"phoneModelId",18L,"colorId",5L,"qty",2L),values("clientRowId","second","rowId",ROW_B,"rowVersion",4L,"phoneModelId",18L,"colorId",5L,"qty",3L)));}
 @Test void bulkPreviewDoesNotAllocateAnyIdentityAndReturnsOnlySourcePhotosAndSupplierColors(){batchSource(true);var request=batchRequest();var first=maps(request.get("rows")).get(0);first.put("colorId",0L);long before=jdbc.queryForObject("select last_value from plm_partner_record_record_id_seq",Long.class);var result=samples.receiptPreview(900L,request);assertEquals(false,result.get("canSave"));var preview=maps(result.get("rows")).get(0);assertEquals("QA-XD",preview.get("supplierCode"));assertEquals(1,maps(preview.get("refs")).size());assertEquals(List.of(5L,7L),maps(preview.get("colors")).stream().map(c->number(c.get("id"))).toList());assertFalse(preview.toString().contains("其他供方"));assertFalse(preview.toString().contains("unitPrice"));assertEquals(0L,count("sample"));assertEquals(before,jdbc.queryForObject("select last_value from plm_partner_record_record_id_seq",Long.class));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_event",Long.class));}
 @Test void bulkReceiptCreatesActualSPsAtomicallyAndRetryReturnsTheSameResultAfterSourceVersionChanges(){batchSource(true);var request=batchRequest();maps(request.get("rows")).get(1).put("colorId",7L);String frozen=jdbc.queryForObject("select data::text from plm_partner_selection_row where row_id=?::uuid",String.class,ROW_B);var saved=tx.execute(s->samples.receiveSelection(900L,request));assertEquals(2,saved.get("batchCount"));assertEquals(2L,count("sample"));assertEquals(0L,count("product"));assertEquals(0L,count("inspection"));var batches=maps(saved.get("batches"));assertEquals(List.of(2L,3L),batches.stream().map(b->number(b.get("qty"))).toList());assertEquals(List.of("黑色","蓝色"),batches.stream().map(b->text(b.get("colorName"))).toList());for(var batch:batches){var sample=samples.detail(number(batch.get("id")));assertTrue(text(sample.get("displayLabel")).startsWith("XD-SP-"));assertEquals("QA国内工程",sample.get("custodian"));assertEquals("2026-10-22",sample.get("receivedDate"));assertEquals(1,maps(sample.get("files")).size());assertFalse(text(sample.get("qualityBasis")).isEmpty());}assertEquals(frozen,jdbc.queryForObject("select data::text from plm_partner_selection_row where row_id=?::uuid",String.class,ROW_B));jdbc.update("update plm_partner_record set version=4 where record_id=900");assertEquals(signature(store.json,saved),signature(store.json,tx.execute(s->samples.receiveSelection(900L,new TreeMap<>(request)))));var changed=copy(store.json,request);changed.put("location","QA另一柜");assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,changed)));assertEquals(2L,count("sample"));}
 @Test void bulkInvalidColorConflictOrCancelledSourceLeavesEverySampleUncreated(){batchSource(true);for(var change:List.of(values("colorId",9L),values("phoneModelId",99L),values("qty",0),values("rowVersion",3L))){var request=copy(store.json,batchRequest());maps(request.get("rows")).get(1).putAll(change);assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,request)));assertEquals(0L,count("sample"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_create_request",Long.class));}jdbc.update("update plm_partner_selection_row set data=jsonb_set(data,'{discarded}','true'::jsonb) where row_id=?::uuid",ROW_B);assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,batchRequest())));assertEquals(0L,count("sample"));}
 @Test void bulkAuditFailureInTheSecondBatchRollsBackTheFirstBatchAndAllFilesAndRequestRecords(){batchSource(true);var calls=new java.util.concurrent.atomic.AtomicInteger();doAnswer(c->{if(calls.incrementAndGet()==2)throw new IllegalStateException("QA second mandatory audit unavailable");return null;}).when(audit).logRequired(any(),any());assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,batchRequest())));assertEquals(0L,count("sample"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_event",Long.class));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_create_request",Long.class));assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_file",Long.class));}
 @Test void bulkPermissionIsRecheckedBeforeReadingOrReplayingReceiptResults(){batchSource(true);var saved=tx.execute(s->samples.receiveSelection(900L,batchRequest()));doThrow(new IllegalStateException("QA no domestic engineering access")).when(access).requireEngineeringMaintenance();assertThrows(RuntimeException.class,()->samples.receiptPreview(900L,batchRequest()));assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,batchRequest())));assertEquals(2L,count("sample"));assertEquals(2,maps(saved.get("batches")).size());}
 @Test void oldMissingColorSnapshotCannotBeReinterpretedAsLateColorAndExplicitPairsStillRestrictReceipt(){batchSource(false);var request=batchRequest();maps(request.get("rows")).get(1).put("colorId",7L);assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,request)));jdbc.update("update plm_partner_selection_row set data=jsonb_set(data-'receiptColorMode'-'selectionConfirmationVersion','{confirmationSnapshot,row,selectedPairs}','[]'::jsonb) where row_id=?::uuid",ROW_B);assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,batchRequest())));assertEquals(0L,count("sample"));}
 @Test void explicitUnavailableActualPairCannotBeReceivedEvenWithColorPendingAtSelection(){batchSource(true);jdbc.update("update plm_partner_selection_row set data=jsonb_set(data,'{confirmationSnapshot,row,pairings}',?::jsonb) where row_id=?::uuid",encode(store.json,List.of(values("phoneModelId",18L,"colorId",5L,"state","unavailable"))),ROW_B);assertThrows(RuntimeException.class,()->tx.execute(s->samples.receiveSelection(900L,batchRequest())));assertEquals(0L,count("sample"));}
 @Test void rawSupplyCostsNeverLeakThroughNoCostSourcePreviewOrActualReceipt(){batchSource(true);var facts=List.of(values("phoneModelId",18L,"colorId",5L,"state","unverified","unitPrice","777.39","currency","USD","terms","QA秘密付款条件","evidence","QA私密自由文报价"));jdbc.update("update plm_partner_selection_row set data=jsonb_set(data,'{confirmationSnapshot,row,pairings}',?::jsonb)",encode(store.json,facts));var styles=(PartnerCatalogStyles)ReflectionTestUtils.getField(samples,"catalogStyles");var source=styles.selectedSnapshot(900L,ROW_A);var preview=samples.receiptPreview(900L,batchRequest());var saved=tx.execute(s->samples.receiveSelection(900L,batchRequest()));for(var value:List.of(source,preview,samples.detail(number(maps(saved.get("batches")).get(0).get("id")))))for(String secret:List.of("777.39","USD","QA秘密付款条件","QA私密自由文报价","unitPrice","terms"))assertFalse(value.toString().contains(secret),secret);}
 @Test void lateColorListingUsesOnlyReceivedPairsAndStillRequiresTheExistingSignedQualityGate(){batchSource(true);ReflectionTestUtils.setField(listings,"catalogStyles",ReflectionTestUtils.getField(samples,"catalogStyles"));assertTrue(maps(listings.catalogOptions(900L,ROW_A).get("pairs")).isEmpty());var request=batchRequest();request.put("rows",List.of(maps(request.get("rows")).get(0)));var saved=tx.execute(s->samples.receiveSelection(900L,request));var options=listings.catalogOptions(900L,ROW_A);var pairs=maps(options.get("pairs"));assertEquals(1,pairs.size());assertEquals(5L,number(pairs.get(0).get("colorId")));assertEquals(false,pairs.get(0).get("eligible"));assertFalse(pairs.stream().anyMatch(p->number(p.get("colorId"))==7L));assertThrows(RuntimeException.class,()->tx.execute(s->listings.confirmCatalog(confirmRequest())));assertEquals(0L,count("product"));assertEquals(0L,count("listing"));long sid=number(maps(saved.get("batches")).get(0).get("id"));var sample=samples.detail(sid);var qc=tx.execute(s->operations.create("inspection",values("parentId",sid,"name","QA晚定色质检","requestId","QA-late-qc-create")));var scope=new LinkedHashMap<>(maps(sample.get("qualityScope")).get(0));scope.put("checkedQty",2L);long qid=number(qc.get("id"));var confirmed=tx.execute(s->operations.action("inspection",qid,"confirm",values("version",1L,"requestId","QA-late-qc-confirm","date","2026-10-22","factory","QA工厂","checks","QA实际规格检查","result","pass","onsite",true,"scope",List.of(scope),"refs",List.of())));assertEquals(false,maps(listings.catalogOptions(900L,ROW_A).get("pairs")).get(0).get("eligible"));long file=jdbc.queryForObject("insert into plm_attachment(file_name,version_no,content_type,checksum) values('QA签名.png','V1','image/png','qa-sign') returning attachment_id",Long.class);jdbc.update("insert into plm_partner_file values(?,?,'factory_signature')",qid,file);var signed=tx.execute(s->operations.action("inspection",qid,"sign",values("version",confirmed.get("version"),"requestId","QA-late-sign","basisHash",confirmed.get("basisHash"),"reviewed",true,"signatureFileId",file,"representativeName","QA工厂代表","representativePosition","QA岗位")));tx.execute(s->operations.action("inspection",qid,"reference",values("version",signed.get("version"),"requestId","QA-late-reference","location","QA公司柜","custodian","QA国内工程","reason","QA对照样品","date","2026-10-22")));assertEquals(true,maps(listings.catalogOptions(900L,ROW_A).get("pairs")).get(0).get("eligible"));assertEquals(0L,count("product"));var unreceived=confirmRequest();unreceived.put("selectedPairs",List.of(Map.of("phoneModelId",18L,"colorId",7L)));assertThrows(RuntimeException.class,()->tx.execute(s->listings.confirmCatalog(unreceived)));var listing=tx.execute(s->listings.confirmCatalog(confirmRequest()));assertEquals("not_connected",listing.get("status"));assertEquals(1L,count("product"));}
 @Test void concurrentBulkRetryCreatesOnlyTheOriginalTwoBatches() throws Exception {batchSource(true);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{Callable<Map<String,Object>> receive=()->{start.await();return tx.execute(s->samples.receiveSelection(900L,batchRequest()));};var one=pool.submit(receive);var two=pool.submit(receive);start.countDown();assertEquals(signature(store.json,one.get(15,TimeUnit.SECONDS)),signature(store.json,two.get(15,TimeUnit.SECONDS)));assertEquals(2L,count("sample"));assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_event where action='sample_receipts'",Long.class));}finally{pool.shutdownNow();}}
 @Test void severalActualModelsAndColorsOfOneStyleDoNotExpandIntoCartesianReceipts(){batchSource(true);jdbc.update("update plm_partner_selection_row set data=jsonb_set(jsonb_set(data,'{confirmationSnapshot,row,phoneModelIds}','[18,12]'::jsonb),'{confirmationSnapshot,row,phones}',?::jsonb) where row_id=?::uuid",encode(store.json,List.of(values("phoneModelId",18L,"displayName","iPhone18 Pro Max"),values("phoneModelId",12L,"displayName","iPhone12"))),ROW_A);var request=batchRequest();request.put("rows",List.of(values("clientRowId","a","rowId",ROW_A,"rowVersion",4L,"phoneModelId",18L,"colorId",5L,"qty",2L),values("clientRowId","b","rowId",ROW_A,"rowVersion",4L,"phoneModelId",18L,"colorId",7L,"qty",1L),values("clientRowId","c","rowId",ROW_A,"rowVersion",4L,"phoneModelId",12L,"colorId",7L,"qty",3L)));var saved=tx.execute(s->samples.receiveSelection(900L,request));assertEquals(3,maps(saved.get("batches")).size());assertEquals(3L,count("sample"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_record where kind='sample' and data->>'phoneModelId'='12' and data->>'colorId'='5'",Long.class));assertEquals(0L,count("product"));}
 private Map<String,Object> confirmRequest(){return values("selectionId",900L,"selectionRowId",snapshot.get("selectionRowId"),"selectionVersion",3L,"selectionRowVersion",4L,"selectedPairs",List.of(Map.of("phoneModelId",18L,"colorId",5L)),"productLinkMode","create","name","QA经营款","introduction","QA实际选定的经营规格","requestId","QA-listing");}
 private Map<String,Object> signedInspection(){
  var sample=receive();var qc=tx.execute(s->operations.create("inspection",values("parentId",sample.get("id"),"name","QA样品质检","requestId","QA-qc-create")));var scope=new LinkedHashMap<>(maps(sample.get("qualityScope")).get(0));scope.put("checkedQty",2L);
  qc=tx.execute(s->operations.action("inspection",number(qcId("QA样品质检")),"confirm",values("version",1L,"requestId","QA-qc-confirm","date","2026-10-22","factory","QA供应商工厂","checks","QA检查实际型号、颜色、结构","result","pass","onsite",true,"scope",List.of(scope),"refs",List.of())));
  long id=number(qc.get("id"));long file=jdbc.queryForObject("insert into plm_attachment(file_name,version_no,content_type,checksum) values('QA模拟工厂代表签名.png','V1','image/png','qa-signature') returning attachment_id",Long.class);jdbc.update("insert into plm_partner_file values(?,?,'factory_signature')",id,file);
  var confirmed=qc;qc=tx.execute(s->operations.action("inspection",id,"sign",values("version",confirmed.get("version"),"requestId","QA-sign","basisHash",confirmed.get("basisHash"),"reviewed",true,"signatureFileId",file,"representativeName","QA工厂代表","representativePosition","QA岗位")));
  var signed=qc;return tx.execute(s->operations.action("inspection",id,"reference",values("version",signed.get("version"),"requestId","QA-reference","location","QA公司样品柜","custodian","QA国内工程","reason","QA本次适用规格对照","date","2026-10-22")));
 }
 private Long qcId(String name){return jdbc.queryForObject("select record_id from plm_partner_record where name=? and kind='inspection'",Long.class,name);}
 @Test void actualReceiptCreatesOnlySPWithRealQuantityAndRepeatKeepsIt(){var sample=receive();assertEquals(1L,count("sample"));assertEquals(0L,count("product"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_spec",Long.class));assertEquals("XD-"+sample.get("code"),sample.get("displayLabel"));assertEquals(2L,map(sample.get("balances")).get("onhand"));assertEquals(23L,number(sample.get("catalogStyleId")));assertEquals(sample.get("id"),tx.execute(s->samples.create(receipt())).get("id"));assertEquals(1L,count("sample"));assertThrows(RuntimeException.class,()->tx.execute(s->samples.create(values("sourceType","catalog","pending",true,"requestId","QA-fake-opening"))));}
 @Test void changedReceiptCannotSilentlyReuseARequestOrCreateAnotherBatch(){
  var original=receive();String frozen=signature(store.json,original);
  for(var change:List.of(Map.of("qty",3),Map.of("phoneModelId",19),Map.of("selectionId",901),Map.of("location","QA其他位置"))){var request=receipt();request.putAll(change);assertThrows(RuntimeException.class,()->tx.execute(s->samples.create(request)));}
  var reordered=new TreeMap<>(receipt());assertEquals(original.get("id"),tx.execute(s->samples.create(reordered)).get("id"));assertEquals(frozen,signature(store.json,samples.detail(number(original.get("id")))));assertEquals(1L,count("sample"));assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_event where action='receive'",Long.class));
 }
 @Test void historicalReceiptWithoutRequestDigestStaysReadableButCannotBeBlindlyReplayed(){
  var received=receive();long id=number(received.get("id"));jdbc.update("update plm_partner_record set data=data-'receiptRequestHash' where record_id=?",id);var old=samples.detail(id);assertEquals(received.get("code"),old.get("code"));assertEquals(received.get("displayLabel"),old.get("displayLabel"));assertThrows(RuntimeException.class,()->tx.execute(s->samples.create(receipt())));assertEquals(1L,count("sample"));assertEquals(2L,map(samples.detail(id).get("balances")).get("onhand"));
 }
