 @Test void legacyPhoneSearchIsPagedScopedAndPreservesLeadingZerosWithoutSearchingCostJson(){
  var ids=new ArrayList<Long>();for(int i=0;i<2;i++){
   long pid=tx.execute(s->store.create("product","QA历史商品"));ids.add(pid);
   var phone=Map.of("modelName","QA-LEGACY-MODEL","displayName","QA-LEGACY-DISPLAY","phoneModelCode",i==0?"0007":"0185");
   var legacy=values("name","QA历史商品","status","draft","listing","listed","notes","QA-PRIVATE-COST-NOT-SEARCHABLE","specs",List.of(Map.of("phones",List.of(phone),"sources",List.of(Map.of("terms","QA-SECRET-TERMS")))));
   tx.executeWithoutResult(s->store.save(pid,legacy));
  }
  var first=listings.catalogPage(Map.of("status","listed","keyword","QA-LEGACY-MODEL","page","1","size","1"));var second=listings.catalogPage(Map.of("status","listed","keyword","QA-LEGACY-MODEL","page","2","size","1"));assertEquals(2L,first.get("totalElements"));assertEquals(2L,first.get("totalPages"));assertEquals(1,maps(first.get("content")).size());assertEquals(1,maps(second.get("content")).size());assertNotEquals(maps(first.get("content")).get(0).get("productId"),maps(second.get("content")).get(0).get("productId"));assertEquals(2L,listings.catalogPage(Map.of("status","listed","keyword","QA-LEGACY-DISPLAY")).get("totalElements"));assertEquals(1L,listings.catalogPage(Map.of("status","listed","keyword","0007")).get("totalElements"));assertEquals(1L,listings.catalogPage(Map.of("status","listed","keyword","0185")).get("totalElements"));for(String keyword:List.of("00007","QA-PRIVATE-COST-NOT-SEARCHABLE","QA-SECRET-TERMS"))assertEquals(0L,listings.catalogPage(Map.of("status","listed","keyword",keyword)).get("totalElements"));
  when(access.visibleSqlClause(eq("partner"),eq("p.record_id"))).thenReturn("p.record_id<>"+ids.get(0));assertEquals(0L,listings.catalogPage(Map.of("status","listed","keyword","0007")).get("totalElements"));assertEquals(1L,listings.catalogPage(Map.of("status","listed","keyword","QA-LEGACY-MODEL")).get("totalElements"));assertEquals("listed",store.load(ids.get(0),"product",false).get("listing"));
 }
